{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, has oral bioavailability ≤3% in patients, showing that extensive sulfation and polarity cause negligible oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dextran sulfate is reported to have poor oral bioavailability in humans, consistent with highly sulfated carbohydrate structures being poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Zanamivir, a polar carbohydrate-like drug with multiple ionizable groups, has an absolute oral bioavailability of only 2% in healthy volunteers, directly supporting low F for similarly polar sugar-acid structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Acamprosate, a small zwitterionic sulfonate, has an absolute oral bioavailability of 11 ± 1% in healthy volunteers, demonstrating that even small polar ionized molecules fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "N-acetylcysteine has an oral bioavailability of about 10% in healthy subjects, with multiple direct measurements in the 4–10% range, supporting low F for polar, ionizable molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Glucoraphanin, a sulfated polar glucosinolate, has an oral bioavailability of about 5% in humans, reinforcing that sulfate-containing hydrophilic molecules are poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Puerarin, a glycoside with multiple polar hydroxyls, exhibits low oral bioavailability in animals and humans, supporting the pattern that sugar-containing polar molecules have poor oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "One report claims oral acetylcysteine bioavailability around 80%, but this is an outlier contradicted by numerous direct measurements showing 4–10% bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, ionized sulfated N-acetylglucosamine-glucuronic acid disaccharide. Multiple high-transfer experimental analogues—pentosan polysulfate (≤3%), dextran sulfate (poor), zanamivir (2%), acamprosate (11%), N-acetylcysteine (4–10%), and glucoraphanin (5%)—consistently show low oral bioavailability due to poor permeability. The single 80% NAC report is an outlier and does not outweigh the direct, repeated low-F measurements. Therefore, oral bioavailability is predicted to be below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query disaccharide.",
    "Possible active uptake or transporter-mediated absorption has not been experimentally assessed for this specific molecule.",
    "Gastrointestinal stability and potential hydrolysis of the sulfate ester or glycosidic linkage are not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

